-- Explicit, one-time migration of opaque public race URLs (25 October 2026).
-- Names/places/edition years come from existing catalogue fields, not new evidence.
-- The stable eight-character legacy suffix keeps separate records separate.
-- Existing triggers preserve every old address in slug_redirects atomically.
-- Keep this map for fresh seeds; never derive established URLs from later name edits.
create table if not exists catalogue_event_slug_migrations (
  old_slug text primary key,
  current_slug text not null unique,
  check (old_slug <> current_slug)
);

